    body += `<g class="b2"><path class="draw draw2" pathLength="1" style="transition-delay:.5s" d="${ptsD(curve(PAR, SPB, -30))}" stroke="${C.blue}" stroke-width="4" fill="none"/></g>`;
    body += at(2, 'pop', lab(Lb.fr[0], Lb.fr[1], '프랑스', { size: 20 }), 0.3) + at(2, 'pop', lab(Lb.ru[0], Lb.ru[1], '러시아', { size: 20 }), 0.5);
    body += at(2, 'pop', tag(...P(v, 28, 62), '1894', COLD), 1.2);
    body += at(3, 'fin', fillSet(v, W14.gb, C.blue, { op: 0.55 }));
    body += `<g class="b3"><path class="draw draw3" pathLength="1" style="transition-delay:.3s" d="${ptsD([LON, PAR])}" stroke="${C.blue}" stroke-width="4" fill="none"/><path class="draw draw3" pathLength="1" style="transition-delay:.9s" d="${ptsD(curve(LON, SPB, -20))}" stroke="${C.blue}" stroke-width="4" fill="none"/></g>`;
    body += at(3, 'pop', lab(Lb.gb[0], Lb.gb[1], '영국', { size: 20 }), 0.2);
    body += at(3, 'pop', tag(...P(v, -8, 47.2), '1904', COLD), 0.6) + at(3, 'pop', tag(...P(v, 12, 61), '1907', COLD), 1.2);
    body += at(2, 'fin', cityDot(...PAR, C.blue, 6) + cityDot(...SPB, C.blue, 6)) + at(3, 'fin', cityDot(...LON, C.blue, 6));
    body += at(4, 'pop', tag(110, 326, '3국 협상 1907', COLD, { size: 22 }), 0.2);
    body += `<g class="b4"><path class="flash flash4" d="${ptsD([LON, PAR, ...curve(PAR, SPB, -30).slice(1), ...curve(SPB, LON, 20).slice(1)])}" stroke="${C.blue}" stroke-width="8" stroke-linejoin="round" fill="none" opacity=".5"/></g>`;
    put(KEY(6, '3국 협상'), svg(id, body, css));
