    body += shown(4, [130, 220].map((y, i) => trip(i ? [400, y] : [574, y], i ? [574, y] : [400, y], `<circle r="7" fill="${C.green}"/>`, { dur: 2.2, delay: i * 0.6 })).join(''));
    // 3칸: 서베를린을 빙 두른 벽
