    body += `<g class="h4">${at(3, 'pop', xMark(530, 130, 9) + xMark(530, 220, 9), 1.2)}${at(3, 'pop', tag(472, 40, '1961 벽', PLAIN, { size: 20 }), 0.8)}</g>`;
    // 4칸: 벽이 열림
    body += at(4, 'pop', tag(472, 40, '1989.11 열림', OK, { size: 20 }), 0.3);
    body += at(4, 'pop', tag(150, 326, '베를린 장벽', PLAIN, { size: 22 }), 0.8);
