    body += lab(...P(v, -98, 37), '미국', { size: 22, color: C.blue });
    body += at(1, 'fin', fillSet(v, ['CU'], C.red, { op: 0.6 }));
    body += at(1, 'pop', lab(CU[0] + 6, CU[1] + 34, '쿠바', { size: 20, color: C.red }), 0.3);
    body += at(1, 'pop', rocket(HAV[0] - 4, HAV[1] - 4, C.red, 20, 1.1), 0.6);
    body += shown(1, trip([640, 200], [520, 232], `<g transform="scale(1.5)">${ship(C.red)}</g>`, { dur: 2.6 }), 3);
    body += at(1, 'pop', tag(560, 160, '소련 배', RED), 0.4);
