    // 어느 편에도 들지 않은 아시아·아프리카 나라(1961년 베오그라드 회의 참가국)는 옅게, 1960년에 독립한 아프리카 나라는 짙게 칠한다.
    const NAM = ['AF', 'DZ', 'MM', 'KH', 'LK', 'ET', 'ER', 'GH', 'GN', 'IN', 'ID', 'IQ', 'LB', 'MA', 'NP', 'SA', 'SD', 'SS', 'TN', 'EG', 'SY', 'YE'];
    body += at(3, 'fin', fillSet(v, NAM, C.green, { op: 0.4 }), 0.1);
