  // ── 비동맹 중립: 두 편이 끌어들임 → 어느 편도 들지 않음 → 1961 베오그라드에 모임 → 비동맹 중립 ──
  const BELG = ['AF', 'DZ', 'MM', 'KH', 'LK', 'CD', 'CU', 'CY', 'CY-N', 'ET', 'ER', 'GH', 'GN', 'IN', 'ID', 'IQ', 'LB', 'ML', 'MA', 'NP', 'SA', 'SO', 'SO-L', 'SD', 'SS', 'TN', 'EG', 'SY', 'YE', 'RS', 'HR', 'BA', 'SI', 'MK', 'ME', 'XK'];
